// Pega o CSV como texto vindo do HTTP Request

const csvRaw = $json.data ?? $json.body ?? $json;

const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);



const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);

const headers = lines[0].split(",").map(h => h.trim());



const investimentos = lines.slice(1).map(line => {

  const cols = line.split(",").map(c => c.trim());

  const obj = {};

  headers.forEach((h, i) => obj[h] = cols[i] ?? "");



  // normaliza mínimo para número

  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;



  return obj;

});



return [{ json: { investimentos } }];

// 1. Função de sorteio aleatório
function pick(arr) {
  if (!arr || arr.length === 0) return "";
  const index = Math.floor(Math.random() * arr.length);
  return arr[index];
}

// 2. Extrai os dados unificados que chegaram do nó anterior
const itemEntrada = $input.first().json;
const clientes = itemEntrada.body?.clientes || [];
const investimentos = itemEntrada.investimentos || [];

// 3. Processa cada cliente
const resultados = clientes.map(c => {
  const perfil = c.perfil;

  // Normaliza o saldo brasileiro: "R$ 12.500,00" -> 12500
  const saldoLimpo = String(c.saldo || "")
    .replace(/[R$\s]/g, "")
    .replace(/\./g, "")
    .replace(",", ".");
  const saldoNum = parseFloat(saldoLimpo) || 0;

  // Filtra por perfil compatível e saldo suficiente
  const compativeis = investimentos.filter(inv => {
    return inv.perfil.toLowerCase() === perfil.toLowerCase() && saldoNum >= inv.minimo;
  });

  // Se o cliente tem mais de R$ 1.000, descarta Poupança/ativos básicos se houver opção melhor
  const opcoesSemPoupanca = compativeis.filter(inv => inv.produto.toLowerCase() !== "poupança");
  const opcoesValidas = (opcoesSemPoupanca.length > 0) ? opcoesSemPoupanca : compativeis;

  // Seleciona o investimento de maior valor mínimo compatível com o saldo
  const escolhido = opcoesValidas.length > 0 
    ? opcoesValidas.sort((a, b) => b.minimo - a.minimo)[0] 
    : null;

  let motivo = "";
  let mensagens = [];

  if (escolhido) {
    motivo = "saldo_ok";

    // Formatação em Real (R$ 1.000,00)
    const minimoTexto = Number(escolhido.minimo || 0).toLocaleString("pt-BR", {
      style: "currency",
      currency: "BRL"
    });

    // As 3 variações exatas mostradas no painel da aula:
    mensagens = [
      `Olá ${c.nome}! Pelo seu perfil (${perfil}), uma boa opção é **${escolhido.produto}** (mínimo ${minimoTexto}). Com seu saldo atual (${c.saldo}), você já consegue investir. Rentabilidade: ${escolhido.rentabilidade}.`,
      `Oi ${c.nome}! Recomendação para perfil ${perfil}: **${escolhido.produto}** (mínimo ${minimoTexto}). Seu saldo (${c.saldo}) já atende o mínimo. Rentabilidade: ${escolhido.rentabilidade}.`,
      `${c.nome}, indo direto ao ponto: para o perfil ${perfil}, indicamos o produto **${escolhido.produto}** (mínimo ${minimoTexto}). Você possui ${c.saldo} em conta, o que viabiliza o aporte. Rentabilidade: ${escolhido.rentabilidade}.`
    ];
  } else {
    motivo = "saldo_insuficiente";

    mensagens = [
      `Olá ${c.nome}! Analisamos seu perfil (${perfil}), mas no momento não encontramos opções disponíveis com aporte mínimo compatível com o seu saldo atual (${c.saldo}).`,
      `Oi ${c.nome}! No momento você precisa de um saldo um pouco maior para acessar as opções disponíveis para o perfil ${perfil}. Continue acompanhando!`
    ];
  }

  return {
    nome: c.nome,
    email: c.email,
    perfil: perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo: motivo,
    mensagens: mensagens,
    mensagem_escolhida: pick(mensagens)
  };
});

// 4. Retorno no formato exato da aula
return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados: resultados
  }
}];

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// Retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

// Obtém o texto gerado pelo Groq
const textoBruto = $json.output?.[0]?.content?.[0]?.text 
  || $json.text 
  || $json.content 
  || "";

const jsonLimpo = textoBruto.replace(/```json/gi, "").replace(/```/g, "").trim();

let emailFormatado = {};
try {
  emailFormatado = JSON.parse(jsonLimpo);
} catch (e) {
  emailFormatado = {
    subject: "Sugestão de Investimento",
    text_body: textoBruto,
    html_body: `<p>${textoBruto.replace(/\n/g, "<br/>")}</p>`
  };
}

// Em vez de $('Nome'), usamos o histórico de execução do item atual:
// Pega o item do nó de onde o Groq recebeu os dados:
const dadosEntrada = $input.item.json;

return {
  json: {
    to: dadosEntrada.email_to || dadosEntrada.email || "",
    nome: dadosEntrada.nome || "",
    subject: emailFormatado.subject,
    text_body: emailFormatado.text_body,
    html_body: emailFormatado.html_body
  }
};

